const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point(153.20, -29.69); // Grafton, New South Wales
  const canberra = ee.Geometry.Point(149.13, -35.28); // Canberra
  const startDate = '2020-01-15';
  const endDate = '2020-01-21'; // End date is exclusive in filterDate, so 21st covers up to 20th, to include 21st, need to set it to 22nd.

  // Correcting the end date to include Jan 21st
  const filterEndDate = '2020-01-22'; // This will include data for Jan 21st.

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, filterEndDate)
    .select('precipitation');

  const chirpsSize = await chirps.size().getInfo();
  if (chirpsSize === 0) {
    console.log("No CHIRPS data found for the specified date range.");
    console.log("C1");
    return;
  }
  console.log(`CHIRPS images found: ${chirpsSize}`);

  // 3. Processing: Calculate total rainfall for the period
  // Sum all daily precipitation images into a single image.
  const totalPrecipitation = chirps.sum();

  // Define a reasonable scale for point reduction. CHIRPS resolution is ~5.5km.
  const scale = 5000; // meters

  // Reduce region for Grafton
  const graftonPrecipitationResult = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: grafton,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Reduce region for Canberra
  const canberraPrecipitationResult = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canberra,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 4. Validation & Final Answer
  if (graftonPrecipitationResult === null || isNaN(graftonPrecipitationResult) ||
      canberraPrecipitationResult === null || isNaN(canberraPrecipitationResult)) {
    console.log("Calculation failed: One or both precipitation values are null or NaN.");
    console.log("C3");
    return;
  }

  console.log(`Grafton total rainfall: ${graftonPrecipitationResult.toFixed(2)} mm`);
  console.log(`Canberra total rainfall: ${canberraPrecipitationResult.toFixed(2)} mm`);

  if (graftonPrecipitationResult > canberraPrecipitationResult) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
